def valid(number):
    """Return True if number passes the Luhn check.

    Spaces are ignored. After removing spaces, the value must contain at
    least two ASCII digits (0-9) and nothing else.
    """
    if not isinstance(number, str):
        return False

    digits = number.replace(" ", "")
    if len(digits) < 2 or any(ch not in "0123456789" for ch in digits):
        return False

    total = 0
    for index, ch in enumerate(reversed(digits)):
        digit = ord(ch) - ord("0")
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
